-- Esquema MÍNIMO das tabelas acadêmicas (Fase 2) para testes locais. Rodar após schema_minimo.sql.
CREATE TABLE LISTA_TURMA (ID BIGINT PRIMARY KEY, VALOR VARCHAR(100), DESCRICAO VARCHAR(200));
CREATE TABLE LISTA_TIPO_CURSO (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, VALOR VARCHAR(100), FORMULARIO VARCHAR(100));
CREATE TABLE LISTA_UNIDADE (ID INT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, VALOR VARCHAR(100));
CREATE TABLE LISTA_STATUS_NOTA (ID BIGINT PRIMARY KEY, VALOR VARCHAR(50));
CREATE TABLE LISTA_SITUACAO_AG (ID BIGINT PRIMARY KEY, VALOR VARCHAR(50));
CREATE TABLE LISTA_CATEGORIA_AG (ID BIGINT PRIMARY KEY, VALOR VARCHAR(50));
CREATE TABLE LISTA_PROFESSOR (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, PROFESSOR VARCHAR(200), DATA_CADASTRO DATETIME NULL);
CREATE TABLE LISTA_DISCIPLINA (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, VALOR VARCHAR(200),
  DESCRICAO TEXT, LEITURA_OBRIGATORIA TEXT, CARGA_HORARIA VARCHAR(50));
CREATE TABLE CURSO (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, LISTA_UNIDADE_ID INT NOT NULL,
  LISTA_TIPO_CURSO_ID BIGINT NOT NULL, NOME VARCHAR(200), SUBTITULO VARCHAR(200), DESCRICAO TEXT, CARGA_HORARIA INT, PERIODO INT,
  TIPO_TURMA INT, DATA_CADASTRO DATETIME, MEDIA DECIMAL(10,2), FALTAS_PERMITIDAS DECIMAL(10,2), VALOR DECIMAL(10,2) NOT NULL DEFAULT 0,
  MATRICULA_ABERTA TINYINT(1) NOT NULL DEFAULT 0, FOTO VARCHAR(500), HORAS_ESTAGIO INT, DATA_MATRICULA DATETIME,
  VALOR_MATRICULA DECIMAL(10,2), VALOR_REMATRICULA DECIMAL(10,2), REMATRICULA_ABERTA TINYINT(1) NOT NULL DEFAULT 0,
  DATA_REMATRICULA DATETIME, LIMITE_ALUNOS_TURMA INT, PERIODICIDADE_COBRANCA INT NOT NULL DEFAULT 1, TEMPO_CURSO INT,
  ATIVO TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE DISCIPLINA (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, CURSO_ID BIGINT NOT NULL,
  LISTA_PROFESSOR_ID BIGINT NULL, LISTA_DISCIPLINA_ID BIGINT NULL, CURSANDO TINYINT NULL, DATA_CADASTRO DATETIME,
  PERIODO VARCHAR(50), DATA_INICIO DATETIME, ORDEM INT NULL, DURACAO_DIAS INT NULL,
  FOREIGN KEY (CURSO_ID) REFERENCES CURSO(ID));
CREATE TABLE VIDEO (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, DISCIPLINA_ID BIGINT NOT NULL,
  TITULO VARCHAR(200), DESCRICAO TEXT, URL VARCHAR(1000), DATA_CADASTRO DATETIME, YOUTUBE TINYINT(1) NOT NULL DEFAULT 0,
  VIMEO TINYINT(1) NOT NULL DEFAULT 0, ORDEM INT NULL, FOREIGN KEY (DISCIPLINA_ID) REFERENCES DISCIPLINA(ID));
CREATE TABLE VIDEO_VIEW (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, VIDEO_ID BIGINT NOT NULL,
  USUARIO_ID BIGINT NOT NULL, STATUS BIGINT NOT NULL, TEMPO VARCHAR(50), DATA_CADASTRO DATETIME);
CREATE TABLE AULA (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, DISCIPLINA_ID BIGINT NOT NULL,
  TITULO VARCHAR(200), DESCRICAO TEXT, URL VARCHAR(1000), DATA_AULA DATETIME, INICIO TIME, TERMINO TIME, DATA_CADASTRO DATETIME);
CREATE TABLE ARQUIVO (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, LISTA_DISCIPLINA_ID BIGINT NOT NULL,
  TITULO VARCHAR(200), DESCRICAO TEXT, URL VARCHAR(1000), DATA_CADASTRO DATETIME);
CREATE TABLE PROVA (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, DISCIPLINA_ID BIGINT NOT NULL,
  ATIVA TINYINT(1) NOT NULL DEFAULT 1, VALOR_PROVA DECIMAL(10,2), DATA_CADASTRO DATETIME);
CREATE TABLE QUESTAO_PROVA (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, PROVA_ID BIGINT NOT NULL,
  QUESTAO TEXT, OPCAO_1 TEXT, OPCAO_2 TEXT, OPCAO_3 TEXT, OPCAO_4 TEXT, OPCAO_5 TEXT, CORRETA VARCHAR(1),
  DATA_CADASTRO DATETIME, VALOR DECIMAL(10,2), FOREIGN KEY (PROVA_ID) REFERENCES PROVA(ID));
CREATE TABLE NOTA (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, DISCIPLINA_ID BIGINT NOT NULL,
  USUARIO_ID BIGINT NOT NULL, LISTA_STATUS_NOTA_ID BIGINT NOT NULL, NOTA DECIMAL(10,2), FALTAS INT, DATA_CADASTRO DATETIME,
  NOTA_RECUPERACAO DECIMAL(10,2));
CREATE TABLE NOTA_PROVA (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, QUESTAO_PROVA_ID BIGINT NOT NULL,
  USUARIO_ID BIGINT NOT NULL, ACERTOU_OPCAO_1 TINYINT(1), ACERTOU_OPCAO_2 TINYINT(1), ACERTOU_OPCAO_3 TINYINT(1),
  ACERTOU_OPCAO_4 TINYINT(1), ACERTOU_OPCAO_5 TINYINT(1), NOTA DECIMAL(10,2), DATA_CADASTRO DATETIME, RECUPERACAO TINYINT(1) NOT NULL DEFAULT 0);
CREATE TABLE ESTAGIO (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, CURSO_ID BIGINT NOT NULL,
  USUARIO_ID BIGINT NOT NULL, LISTA_STATUS_NOTA_ID BIGINT NOT NULL, HORAS DECIMAL(10,2), FALTAS INT, DATA_CADASTRO DATETIME);
CREATE TABLE AGENDAMENTO (ID BIGINT AUTO_INCREMENT PRIMARY KEY, USUARIO_ID BIGINT NULL, INSTITUICAO_ID BIGINT NOT NULL,
  LISTA_SITUACAO_AG_ID BIGINT NULL, LISTA_CATEGORIA_AG_ID BIGINT NULL, DATA DATETIME, HORA TIME, OUTROS VARCHAR(200), DESCRICAO TEXT);
CREATE TABLE USUARIO_CURSO (INSTITUICAO_ID BIGINT NOT NULL, USUARIO_ID BIGINT NOT NULL, CURSO_ID BIGINT NOT NULL,
  DATA_CADASTRO DATETIME DEFAULT CURRENT_TIMESTAMP, INSCRICAO_ID BIGINT NULL, PRIMARY KEY (INSTITUICAO_ID, USUARIO_ID, CURSO_ID));

